package org.jlinalg.genetics;

import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.Test;
import static org.jlinalg.genetics.FumaVariantGeneMapping.*;

class FumaVariantGeneMappingTest {
    private static final Filter NONE=new Filter(0,Double.NaN,List.of(),States.ANY,7,List.of(),Binary.ANY);
    private static Gene g(String id,int chr,int start,int end){return new Gene(id,id,chr,start,end,"+","protein_coding");}
    private static Variant v(String id,int chr,int pos,double p,double cadd,double rdb){return new Variant(id,"rs"+id,chr,pos,p,cadd,rdb,"1",List.of("rsLead"));}
    private static Annotation a(String id,double cadd,double rdb){return new Annotation(id,cadd,rdb,Map.of(),Map.of());}
    private static Options o(Integer window,String regex,Filter pos,Filter eq,EqtlSelection select){return new Options("fixture-GRCh37",Set.of(),Mhc.KEEP,null,null,true,window,regex,pos,true,eq,select,1000);}
    private static Options o(Integer window,String regex){return o(window,regex,NONE,NONE,new EqtlSelection(Set.of(),Double.NaN,Double.NaN));}
    private static Eqtl e(String uid,String gene,double p,double q,String direction){return new Eqtl(uid,gene,"GTEx","Brain.txt.gz",p,q,direction);}
    private static Result run(List<Variant> vs,List<Annotation> as,List<Consequence> cs,List<Eqtl> es,Options options){return map(List.of(g("G1",1,100,200),g("G2",1,300,400)),vs,as,cs,es,options);}
    @Test void closedWindowIncludesBothEdgesAndSharesExistingMapper(){var r=run(List.of(v("a",1,50,.01,1,1),v("b",1,250,.02,1,1),v("c",1,251,.03,1,1)),List.of(a("a",1,1),a("b",1,1),a("c",1,1)),List.of(),List.of(),o(50,null));assertEquals(List.of("a","b"),r.positional().stream().filter(p->p.gene().equals("G1")).map(PositionEvidence::uid).toList());assertEquals(List.of("b","c"),r.positional().stream().filter(p->p.gene().equals("G2")).map(PositionEvidence::uid).toList());}
    @Test void negativeExpandedStartRemainsMembershipEquivalentToZeroClipping(){var r=run(List.of(v("a",1,1,.01,1,1)),List.of(a("a",1,1)),List.of(),List.of(),o(1000,null));assertEquals(2,r.positional().size());}
    @Test void regexSearchAndDistinctConsequenceRowsDoNotInflateUniqueCounts(){var cs=List.of(new Consequence("a","G1","exonic"),new Consequence("a","G1","exonic"),new Consequence("a","G1","nonexonic"));var r=run(List.of(v("a",1,100,.01,2,1)),List.of(a("a",3,1)),cs,List.of(),o(null,"exonic"));assertEquals(2,r.positional().size());assertEquals(1,r.genes().get(0).positionalVariants());assertEquals(2,r.genes().get(0).positionalEvidenceRows());assertEquals(3,r.genes().get(0).maxCadd());}
    @Test void scoreSourcesDifferForPositionAndEqtl(){var filter=new Filter(10,2,List.of(),States.ANY,7,List.of(),Binary.ANY);var r=run(List.of(v("a",1,100,.01,20,1),v("b",1,120,.02,0,5)),List.of(a("a",5,3),a("b",15,1)),List.of(),List.of(e("a","G2",.2,.8,"+"),e("b","G2",.3,.9,"-")),o(0,null,filter,filter,new EqtlSelection(Set.of(),Double.NaN,Double.NaN)));assertEquals(List.of("a"),r.positional().stream().map(PositionEvidence::uid).toList());assertEquals(List.of("b"),r.eqtls().stream().map(Eqtl::uid).toList());assertTrue(r.warnings().stream().anyMatch(w->w.startsWith("DISTINCT SCORE SOURCES")));}
    @Test void thresholdEqualityIsIncluded(){var filter=new Filter(10,2,List.of(),States.ANY,7,List.of(),Binary.ANY);var r=run(List.of(v("a",1,100,.01,10,2)),List.of(a("a",10,2)),List.of(),List.of(e("a","G2",.05,.1,"+")),o(0,null,filter,filter,new EqtlSelection(Set.of(),.05,.1)));assertEquals(1,r.positional().size());assertEquals(1,r.eqtls().size());}
    @Test void missingScoresFailEnabledFiltersButDoNotInventZeroScores(){var filter=new Filter(1,Double.NaN,List.of(),States.ANY,7,List.of(),Binary.ANY);var r=run(List.of(v("a",1,100,.01,Double.NaN,1)),List.of(a("a",Double.NaN,1)),List.of(),List.of(),o(0,null,filter,NONE,new EqtlSelection(Set.of(),Double.NaN,Double.NaN)));assertTrue(r.genes().isEmpty());var other=run(List.of(v("a",1,100,.01,Double.NaN,1)),List.of(a("a",Double.NaN,1)),List.of(),List.of(),o(0,null));assertTrue(Double.isNaN(other.genes().get(0).maxCadd()));}
    private static Result states(States method,Map<String,Double> states){var f=new Filter(0,Double.NaN,List.of("s1","s2","s3"),method,7,List.of(),Binary.ANY);return run(List.of(v("a",1,100,.01,1,1)),List.of(new Annotation("a",1,1,states,Map.of())),List.of(),List.of(),o(0,null,f,NONE,new EqtlSelection(Set.of(),Double.NaN,Double.NaN)));}
    @Test void stateAnyUsesMinimumAndAllUsesMaximum(){var s=Map.of("s1",1.0,"s2",8.0,"s3",8.0);assertEquals(1,states(States.ANY,s).positional().size());assertTrue(states(States.ALL,s).positional().isEmpty());assertTrue(states(States.MODE,s).positional().isEmpty());}
    @Test void stateModeTieUsesSmallestNumericState(){assertEquals(1,states(States.MODE,Map.of("s1",7.0,"s2",8.0,"s3",9.0)).positional().size());}
    @Test void modeOmitsMissingButMinMaxPropagateIt(){var s=Map.of("s1",1.0,"s2",Double.NaN,"s3",Double.NaN);assertEquals(1,states(States.MODE,s).positional().size());assertTrue(states(States.ANY,s).positional().isEmpty());assertTrue(states(States.ALL,s).positional().isEmpty());assertTrue(states(States.MODE,Map.of("s1",Double.NaN,"s2",Double.NaN,"s3",Double.NaN)).positional().isEmpty());}
    private static Result binary(Binary method,Map<String,Double> binary){var f=new Filter(0,Double.NaN,List.of(),States.ANY,7,List.of("b1","b2"),method);return run(List.of(v("a",1,100,.01,1,1)),List.of(new Annotation("a",1,1,Map.of(),binary)),List.of(),List.of(),o(0,null,f,NONE,new EqtlSelection(Set.of(),Double.NaN,Double.NaN)));}
    @Test void binaryMajorityIsStrictAndMissingDoesNotPass(){var b=Map.of("b1",1.0,"b2",0.0);assertEquals(1,binary(Binary.ANY,b).positional().size());assertTrue(binary(Binary.MAJORITY,b).positional().isEmpty());assertTrue(binary(Binary.ALL,b).positional().isEmpty());assertTrue(binary(Binary.ANY,Map.of("b1",1.0,"b2",Double.NaN)).positional().isEmpty());}
    @Test void sourceStageDoesNotApplyImplicitEqtlSignificance(){var r=run(List.of(v("a",1,100,Double.NaN,1,1)),List.of(a("a",1,1)),List.of(),List.of(e("a","G2",.9,.99,"+")),o(0,null));assertEquals(1,r.eqtls().size());assertEquals(.9,r.genes().get(1).minEqtlP());assertTrue(Double.isNaN(r.genes().get(1).minGwasP()));}
    @Test void explicitEqtlCutsRejectMissingOrHigherPAndRespectTissue(){var r=run(List.of(v("a",1,100,.01,1,1)),List.of(a("a",1,1)),List.of(),List.of(e("a","G2",.051,.01,"+"),e("a","G2",Double.NaN,.01,"+"),e("a","G2",.05,.1,"-")),o(0,null,NONE,NONE,new EqtlSelection(Set.of("Brain.txt.gz"),.05,.1)));assertEquals(1,r.eqtls().size());assertEquals("-",r.genes().get(1).direction());}
    @Test void summariesUseUniqueVariantsButAllAssociationDirections(){var r=run(List.of(v("a",1,100,.03,1,1),v("b",1,120,.01,1,1)),List.of(a("a",1,1),a("b",1,1)),List.of(),List.of(e("a","G2",.1,.2,"+"),e("a","G2",.2,.3,"+"),e("b","G2",.01,.04,"-")),o(0,null));var g=r.genes().get(1);assertEquals(2,g.eqtlVariants());assertEquals("+",g.direction());assertEquals(List.of("GTEx/Brain"),g.tissues());assertEquals(.01,g.minGwasP());assertEquals(List.of("rsLead"),g.independentRsIds());}
    @Test void directionTieHasDeterministicPlusFirstOrder(){var r=run(List.of(v("a",1,100,.01,1,1)),List.of(a("a",1,1)),List.of(),List.of(e("a","G2",.1,.1,"-"),e("a","G2",.1,.1,"+")),o(0,null));assertEquals("+",r.genes().get(1).direction());}
    private static List<Gene> mhcGenes(){return List.of(new Gene("MOG","MOG",6,1000,1100,"+","protein_coding"),new Gene("COL","COL11A2",6,1900,2000,"+","protein_coding"),g("SPAN",6,900,2100),g("LEFT",6,900,1000),g("RIGHT",6,2000,2100));}
    private static Options mhc(Mhc policy,Integer start,Integer end){return new Options("fixture",Set.of(),policy,start,end,true,1000,null,NONE,false,NONE,new EqtlSelection(Set.of(),Double.NaN,Double.NaN),1000);}
    @Test void endpointMhcRetainsSpanningGeneButFullOverlapRemovesIt(){var vs=List.of(v("a",6,950,.01,1,1));var as=List.of(a("a",1,1));var source=map(mhcGenes(),vs,as,List.of(),List.of(),mhc(Mhc.SOURCE_ENDPOINTS,null,null));assertEquals(List.of("SPAN"),source.genes().stream().map(g->g.gene().id()).toList());assertTrue(map(mhcGenes(),vs,as,List.of(),List.of(),mhc(Mhc.FULL_OVERLAP,null,null)).genes().isEmpty());}
    @Test void customMhcOnlyExpandsAnchors(){var vs=List.of(v("a",6,950,.01,1,1));var as=List.of(a("a",1,1));assertEquals(1,map(mhcGenes(),vs,as,List.of(),List.of(),mhc(Mhc.SOURCE_ENDPOINTS,1200,1800)).genes().size());assertTrue(map(mhcGenes(),vs,as,List.of(),List.of(),mhc(Mhc.SOURCE_ENDPOINTS,900,2100)).genes().isEmpty());}
    @Test void missingOrDuplicatedMhcAnchorsFailExplicitly(){assertThrows(IllegalArgumentException.class,()->map(List.of(g("G1",1,1,2)),List.of(v("a",1,1,.01,1,1)),List.of(a("a",1,1)),List.of(),List.of(),mhc(Mhc.SOURCE_ENDPOINTS,null,null)));}
    @Test void biotypesApplyBeforeMhcAndMapping(){var options=new Options("fixture",Set.of("lncRNA"),Mhc.KEEP,null,null,true,0,null,NONE,false,NONE,new EqtlSelection(Set.of(),Double.NaN,Double.NaN),10);var r=run(List.of(v("a",1,100,.01,1,1)),List.of(a("a",1,1)),List.of(),List.of(),options);assertEquals(List.of("G1","G2"),r.excludedGenes());assertTrue(r.genes().isEmpty());}
    @Test void unknownGenesDoNotBecomeUnannotatedResults(){var r=run(List.of(v("a",1,100,.01,1,1)),List.of(a("a",1,1)),List.of(new Consequence("a","UNKNOWN","exonic")),List.of(e("a","UNKNOWN",.01,.02,"+")),o(null,"exonic"));assertTrue(r.genes().isEmpty());}
    @Test void duplicateCandidateOrMissingAnnotationFails(){var v=v("a",1,100,.01,1,1);assertThrows(IllegalArgumentException.class,()->run(List.of(v,v),List.of(a("a",1,1)),List.of(),List.of(),o(0,null)));assertThrows(IllegalArgumentException.class,()->run(List.of(v),List.of(),List.of(),List.of(),o(0,null)));}
    @Test void evidenceMustReferToKnownCandidate(){assertThrows(IllegalArgumentException.class,()->run(List.of(v("a",1,100,.01,1,1)),List.of(a("a",1,1)),List.of(),List.of(e("b","G2",.01,.02,"+")),o(0,null)));}
    @Test void badStatesAndBinaryValuesFailRatherThanRound(){assertThrows(IllegalArgumentException.class,()->new Annotation("a",1,1,Map.of("s",1.5),Map.of()));assertThrows(IllegalArgumentException.class,()->new Annotation("a",1,1,Map.of(),Map.of("b",2.0)));}
    @Test void missingSelectedTrackFailsRatherThanSkipFilter(){assertThrows(IllegalArgumentException.class,()->states(States.ANY,Map.of("s1",1.0)));}
    @Test void boundedMembershipsFailBeforeOversizedResultIsStored(){var options=new Options("fixture",Set.of(),Mhc.KEEP,null,null,true,1000,null,NONE,false,NONE,new EqtlSelection(Set.of(),Double.NaN,Double.NaN),1);assertThrows(IllegalArgumentException.class,()->run(List.of(v("a",1,100,.01,1,1)),List.of(a("a",1,1)),List.of(),List.of(),options));}
    @Test void windowOverflowFailsRatherThanWrappingChromosomeBounds(){assertThrows(ArithmeticException.class,()->run(List.of(v("a",1,100,.01,1,1)),List.of(a("a",1,1)),List.of(),List.of(),o(Integer.MAX_VALUE,null)));}
    @Test void chromosomeYAndUnalignedDirectionsAreExplicitlyUnsupported(){assertThrows(IllegalArgumentException.class,()->v("a",24,1,.01,1,1));assertThrows(IllegalArgumentException.class,()->e("a","G1",.01,.02,"A/G"));}
}
